/** Rows per `IN (...)` list, safely below SQLite's bound-variable limit. */
const PURGE_CHUNK = 500;

export type PurgedIssues = {
  readonly issueIds: readonly IssueId[];
  readonly commentIds: readonly string[];
  /** Megabytes the deleted attachments were counted for (each rounded up). */
  readonly storageMb: number;
};

const BYTES_PER_MB = 1024 * 1024;

/**
 * Permanently deletes issues with their label links, comments and
 * attachments, in one transaction. Each project's highest issue number is
 * recorded first so the number is never handed out again.
 */
export async function purgeIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<PurgedIssues> {
  const commentIds: string[] = [];
  let storageMb = 0;

  getDb().transaction((tx) => {
    for (let at = 0; at < issueIds.length; at += PURGE_CHUNK) {
      const chunk = issueIds.slice(at, at + PURGE_CHUNK) as IssueId[];

      const doomed = tx
        .select({ projectId: issues.projectId, number: issues.number })
        .from(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, chunk)))
        .all();

