          .values({ projectId, orgId, lastNumber })
          .onConflictDoUpdate({
            target: projectIssueCounters.projectId,
            set: {
              lastNumber: sql`max(${projectIssueCounters.lastNumber}, ${lastNumber})`,
            },
          })
          .run();
      }

      const commentRows = tx
        .select({ id: comments.id })
        .from(comments)
        .where(
          and(
            orgPredicate(comments.orgId, orgId),
            inArray(comments.issueId, chunk),
          ),
        )
        .all();
      for (const row of commentRows) commentIds.push(row.id);

      const attachmentRows = tx
        .select({ sizeBytes: attachments.sizeBytes })
        .from(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, chunk),
          ),
        )
        .all();
      for (const row of attachmentRows) {
        storageMb += Math.ceil(row.sizeBytes / BYTES_PER_MB);
      }

      tx.delete(issueLabels)
        .where(
          and(
            orgPredicate(issueLabels.orgId, orgId),
            inArray(issueLabels.issueId, chunk),
          ),
        )
        .run();
      tx.delete(comments)
        .where(
          and(
            orgPredicate(comments.orgId, orgId),
            inArray(comments.issueId, chunk),
          ),
        )
        .run();
      tx.delete(attachments)
        .where(
          and(
            orgPredicate(attachments.orgId, orgId),
            inArray(attachments.issueId, chunk),
          ),
        )
        .run();
      tx.delete(issues)
        .where(and(orgPredicate(issues.orgId, orgId), inArray(issues.id, chunk)))
        .run();
    }
  });

